/* ===== Persistir historial de Cambios de Password/Login ===== */
SET NOCOUNT ON;

IF OBJECT_ID('OpsObservability.dbo.monitoring_password_changes_history','U') IS NULL
BEGIN
  CREATE TABLE OpsObservability.dbo.monitoring_password_changes_history(
    id                 bigint         IDENTITY(1,1) PRIMARY KEY,
    ts_utc             datetime2      NOT NULL,
    instance_name      sysname        NOT NULL,
    fecha_modificacion datetime2      NULL,
    usuario            sysname        NULL,
    accion             nvarchar(50)   NULL,
    descripcion        nvarchar(4000) NULL,
    estado             nvarchar(20)   NULL
  );
END;

/* Momento de inserción (UTC) */
DECLARE @now_utc datetime2 = GETUTCDATE();

/* instance_name viene del item 0 de Set - Params */
DECLARE @inst sysname = N'{{$item(0).$node["Set - Params"].json["instance_name"]}}';

INSERT INTO OpsObservability.dbo.monitoring_password_changes_history(
  ts_utc,
  instance_name,
  fecha_modificacion,
  usuario,
  accion,
  descripcion,
  estado
)
VALUES(
  @now_utc,
  @inst,
  CASE WHEN '{{$json.ts_sp}}' = '' THEN NULL ELSE CAST('{{$json.ts_sp}}' AS datetime2) END,
  N'{{$json.usuario}}',
  N'{{$json.accion}}',
  N'{{$json.descripcion}}',
  N'{{$json.estado}}'
);

SELECT 1 AS ok;

